//-----------------------------------------------------------------------------
// 2D FFT On-board Wrapper
//
// Purpose:
//   - Expose fft_2D as a board-friendly IP with:
//       * S_AXIS input   (echo stream from AXI DMA MM2S)
//       * M_AXIS output  (FFT stream to AXI DMA S2MM)
//       * S_AXI          (start/status/counters/config)
//       * M_AXI_TRANS    (transpose DDR traffic from internal transpose AXI path)
//
// Notes:
//   - Set FRAME_WORDS to NR*NA (default 1024*512 = 524288) for one frame.
//   - Output TLAST is generated by wrapper based on output handshake count.
//-----------------------------------------------------------------------------
module fft2d_onboard_wrapper #(
    parameter DATA_WIDTH       = 16,
    parameter NR               = 1024,
    parameter NA               = 512,
    parameter AXI_ADDR_WIDTH   = 32,
    parameter AXI_DATA_WIDTH   = 32,
    parameter AXIL_ADDR_WIDTH  = 16,
    parameter AXIL_DATA_WIDTH  = 32,
    parameter AXIL_STRB_WIDTH  = AXIL_DATA_WIDTH / 8,
    parameter [31:0] TRANSPOSE_DDR_BASE_ADDR = 32'h0C40_0000,
    parameter [31:0] DEFAULT_FRAME_WORDS   = NR * NA,
    parameter [31:0] DEFAULT_TIMEOUT_CYCLES = 32'd100_000_000
) (
    input  wire                         aclk,
    input  wire                         aresetn,

    // AXI-Lite slave (control/status)
    input  wire [AXIL_ADDR_WIDTH-1:0]   s_axi_awaddr,
    input  wire [2:0]                   s_axi_awprot,
    input  wire                         s_axi_awvalid,
    output wire                         s_axi_awready,
    input  wire [AXIL_DATA_WIDTH-1:0]   s_axi_wdata,
    input  wire [AXIL_STRB_WIDTH-1:0]   s_axi_wstrb,
    input  wire                         s_axi_wvalid,
    output wire                         s_axi_wready,
    output wire [1:0]                   s_axi_bresp,
    output wire                         s_axi_bvalid,
    input  wire                         s_axi_bready,
    input  wire [AXIL_ADDR_WIDTH-1:0]   s_axi_araddr,
    input  wire [2:0]                   s_axi_arprot,
    input  wire                         s_axi_arvalid,
    output wire                         s_axi_arready,
    output wire [AXIL_DATA_WIDTH-1:0]   s_axi_rdata,
    output wire [1:0]                   s_axi_rresp,
    output wire                         s_axi_rvalid,
    input  wire                         s_axi_rready,

    // S_AXIS_ECHO input
    input  wire [DATA_WIDTH*2-1:0]      s_axis_echo_tdata,
    input  wire                         s_axis_echo_tvalid,
    output wire                         s_axis_echo_tready,
    input  wire                         s_axis_echo_tlast,
    input  wire [DATA_WIDTH*2/8-1:0]    s_axis_echo_tkeep,

    // M_AXIS_FFT output
    output wire [DATA_WIDTH*2-1:0]      m_axis_fft_tdata,
    output wire                         m_axis_fft_tvalid,
    input  wire                         m_axis_fft_tready,
    output wire                         m_axis_fft_tlast,
    output wire [DATA_WIDTH*2/8-1:0]    m_axis_fft_tkeep,

    // Optional interrupt output
    output wire                         irq,

    // M_AXI_TRANSPOSE_DDR master
    output wire [AXI_ADDR_WIDTH-1:0]    m_axi_trans_awaddr,
    output wire [7:0]                   m_axi_trans_awlen,
    output wire [2:0]                   m_axi_trans_awsize,
    output wire [1:0]                   m_axi_trans_awburst,
    output wire                         m_axi_trans_awvalid,
    input  wire                         m_axi_trans_awready,
    output wire [AXI_DATA_WIDTH-1:0]    m_axi_trans_wdata,
    output wire [AXI_DATA_WIDTH/8-1:0]  m_axi_trans_wstrb,
    output wire                         m_axi_trans_wlast,
    output wire                         m_axi_trans_wvalid,
    input  wire                         m_axi_trans_wready,
    input  wire [1:0]                   m_axi_trans_bresp,
    input  wire                         m_axi_trans_bvalid,
    output wire                         m_axi_trans_bready,
    output wire [AXI_ADDR_WIDTH-1:0]    m_axi_trans_araddr,
    output wire [7:0]                   m_axi_trans_arlen,
    output wire [2:0]                   m_axi_trans_arsize,
    output wire [1:0]                   m_axi_trans_arburst,
    output wire                         m_axi_trans_arvalid,
    input  wire                         m_axi_trans_arready,
    input  wire [AXI_DATA_WIDTH-1:0]    m_axi_trans_rdata,
    input  wire [1:0]                   m_axi_trans_rresp,
    input  wire                         m_axi_trans_rlast,
    input  wire                         m_axi_trans_rvalid,
    output wire                         m_axi_trans_rready,

    output wire                         sram_WE_n,
    output wire                         sram_CE_n,
    output wire                         sram_CE_2,
    output wire                         sram_OE_n,
    output wire [18:0]                  sram_addr,
    inout  wire [31:0]                  sram_data
);

wire clk = aclk;
wire rst_n = aresetn;

localparam [7:0] REG_CONTROL      = 8'h00;
localparam [7:0] REG_STATUS       = 8'h04;
localparam [7:0] REG_FRAME_WORDS  = 8'h08;
localparam [7:0] REG_TIMEOUT      = 8'h0C;
localparam [7:0] REG_IN_COUNT     = 8'h10;
localparam [7:0] REG_OUT_COUNT    = 8'h14;
localparam [7:0] REG_ERR_COUNT    = 8'h18;
localparam [7:0] REG_VERSION      = 8'h1C;

localparam [31:0] REG_VERSION_VALUE = 32'h4654_3244; // "FT2D"

// AXI-Lite signals
reg                         aw_hs_done;
reg                         w_hs_done;
reg                         bvalid_reg;
reg [AXIL_ADDR_WIDTH-1:0]   awaddr_reg;
reg [AXIL_DATA_WIDTH-1:0]   wdata_reg;
reg [AXIL_STRB_WIDTH-1:0]   wstrb_reg;

reg [AXIL_DATA_WIDTH-1:0]   rdata_reg;
reg                         rvalid_reg;

wire write_commit;
wire read_commit;

wire [7:0] wr_addr;
wire [7:0] rd_addr;

// Control/status registers
reg         cfg_transpose_store_reg;
reg [31:0]  frame_words_reg;
reg [31:0]  timeout_cycles_reg;

reg         run_active;
reg         done_sticky;
reg         timeout_err_sticky;
reg         length_err_sticky;
reg [31:0]  in_count;
reg [31:0]  out_count;
reg [31:0]  err_count;
reg [31:0]  no_progress_cycles;

reg         start_pulse;
reg         clear_status_pulse;
reg         soft_reset_pulse;

// FFT core stream signals
wire [DATA_WIDTH-1:0] fft_o_real;
wire [DATA_WIDTH-1:0] fft_o_imag;
wire                  fft_o_valid;
wire                  fft_i_ready;
wire                  fft_i_valid;
wire                  fft_o_ready;

wire in_hs;
wire out_hs;
wire progress_hs;
wire in_last_expected;
wire out_last_expected;
wire frame_words_nonzero;

function [31:0] apply_wstrb_32;
    input [31:0] old_data;
    input [31:0] new_data;
    input [3:0]  strb;
    integer i;
    begin
        apply_wstrb_32 = old_data;
        for (i = 0; i < 4; i = i + 1) begin
            if (strb[i]) begin
                apply_wstrb_32[i*8 +: 8] = new_data[i*8 +: 8];
            end
        end
    end
endfunction

assign wr_addr = awaddr_reg[7:0];
assign rd_addr = s_axi_araddr[7:0];

assign write_commit = aw_hs_done && w_hs_done && !bvalid_reg;
assign read_commit  = s_axi_arvalid && s_axi_arready;

assign s_axi_awready = !aw_hs_done;
assign s_axi_wready  = !w_hs_done;
assign s_axi_bresp   = 2'b00;
assign s_axi_bvalid  = bvalid_reg;
assign s_axi_arready = !rvalid_reg;
assign s_axi_rdata   = rdata_reg;
assign s_axi_rresp   = 2'b00;
assign s_axi_rvalid  = rvalid_reg;

assign frame_words_nonzero = (frame_words_reg != 32'd0);
assign in_last_expected    = (in_count  == (frame_words_reg - 1'b1));
assign out_last_expected   = (out_count == (frame_words_reg - 1'b1));

assign in_hs       = s_axis_echo_tvalid && s_axis_echo_tready;
assign out_hs      = m_axis_fft_tvalid  && m_axis_fft_tready;
assign progress_hs = in_hs || out_hs;

assign s_axis_echo_tready = run_active && frame_words_nonzero && (in_count < frame_words_reg) && fft_i_ready;
assign fft_i_valid        = run_active && frame_words_nonzero && (in_count < frame_words_reg) && s_axis_echo_tvalid;

assign m_axis_fft_tdata   = {fft_o_real, fft_o_imag};
assign m_axis_fft_tvalid  = run_active && fft_o_valid;
assign m_axis_fft_tlast   = m_axis_fft_tvalid && out_last_expected;
assign m_axis_fft_tkeep   = {(DATA_WIDTH*2/8){1'b1}};

assign fft_o_ready = run_active && m_axis_fft_tready;

assign irq = done_sticky | timeout_err_sticky | length_err_sticky;

initial begin
    if ((AXIL_DATA_WIDTH != 32) || (AXIL_STRB_WIDTH != 4)) begin
        $error("fft2d_onboard_wrapper currently supports AXI-Lite 32-bit data width only.");
    end
end

//-----------------------------------------------------------------------------
// AXI-Lite write/read handling
//-----------------------------------------------------------------------------
always @(posedge clk) begin
    if (!rst_n) begin
        aw_hs_done <= 1'b0;
        w_hs_done  <= 1'b0;
        bvalid_reg <= 1'b0;
        awaddr_reg <= {AXIL_ADDR_WIDTH{1'b0}};
        wdata_reg  <= {AXIL_DATA_WIDTH{1'b0}};
        wstrb_reg  <= {AXIL_STRB_WIDTH{1'b0}};
        rdata_reg  <= {AXIL_DATA_WIDTH{1'b0}};
        rvalid_reg <= 1'b0;

        start_pulse        <= 1'b0;
        clear_status_pulse <= 1'b0;
        soft_reset_pulse   <= 1'b0;

        cfg_transpose_store_reg <= 1'b1;
        frame_words_reg         <= DEFAULT_FRAME_WORDS;
        timeout_cycles_reg      <= DEFAULT_TIMEOUT_CYCLES;
    end else begin
        start_pulse        <= 1'b0;
        clear_status_pulse <= 1'b0;
        soft_reset_pulse   <= 1'b0;

        // AW channel capture
        if (!aw_hs_done && s_axi_awvalid) begin
            aw_hs_done <= 1'b1;
            awaddr_reg <= s_axi_awaddr;
        end

        // W channel capture
        if (!w_hs_done && s_axi_wvalid) begin
            w_hs_done <= 1'b1;
            wdata_reg <= s_axi_wdata;
            wstrb_reg <= s_axi_wstrb;
        end

        // Commit write once both AW/W are captured
        if (write_commit) begin
            case (wr_addr)
                REG_CONTROL: begin
                    if (wstrb_reg[0]) begin
                        if (wdata_reg[0]) start_pulse        <= 1'b1; // W1P
                        if (wdata_reg[1]) clear_status_pulse <= 1'b1; // W1P
                        if (wdata_reg[2]) soft_reset_pulse   <= 1'b1; // W1P
                        cfg_transpose_store_reg <= wdata_reg[3];
                    end
                end
                REG_FRAME_WORDS: begin
                    frame_words_reg <= apply_wstrb_32(frame_words_reg, wdata_reg, wstrb_reg);
                end
                REG_TIMEOUT: begin
                    timeout_cycles_reg <= apply_wstrb_32(timeout_cycles_reg, wdata_reg, wstrb_reg);
                end
                default: begin
                    // RO registers ignore writes
                end
            endcase

            aw_hs_done <= 1'b0;
            w_hs_done  <= 1'b0;
            bvalid_reg <= 1'b1;
        end

        // Write response handshake
        if (bvalid_reg && s_axi_bready) begin
            bvalid_reg <= 1'b0;
        end

        // Read address handshake
        if (read_commit) begin
            case (rd_addr)
                REG_CONTROL: begin
                    rdata_reg <= {28'd0, cfg_transpose_store_reg, 3'd0};
                end
                REG_STATUS: begin
                    rdata_reg <= {
                        24'd0,
                        3'd0,
                        length_err_sticky,
                        timeout_err_sticky,
                        done_sticky,
                        run_active,
                        ~run_active
                    };
                end
                REG_FRAME_WORDS: rdata_reg <= frame_words_reg;
                REG_TIMEOUT:     rdata_reg <= timeout_cycles_reg;
                REG_IN_COUNT:    rdata_reg <= in_count;
                REG_OUT_COUNT:   rdata_reg <= out_count;
                REG_ERR_COUNT:   rdata_reg <= err_count;
                REG_VERSION:     rdata_reg <= REG_VERSION_VALUE;
                default:         rdata_reg <= 32'd0;
            endcase
            rvalid_reg <= 1'b1;
        end

        // Read data handshake
        if (rvalid_reg && s_axi_rready) begin
            rvalid_reg <= 1'b0;
        end
    end
end

//-----------------------------------------------------------------------------
// Run control, counters, timeout/error tracking
//-----------------------------------------------------------------------------
always @(posedge clk) begin
    if (!rst_n) begin
        run_active         <= 1'b0;
        done_sticky        <= 1'b0;
        timeout_err_sticky <= 1'b0;
        length_err_sticky  <= 1'b0;
        in_count           <= 32'd0;
        out_count          <= 32'd0;
        err_count          <= 32'd0;
        no_progress_cycles <= 32'd0;
    end else begin
        if (soft_reset_pulse) begin
            run_active         <= 1'b0;
            done_sticky        <= 1'b0;
            timeout_err_sticky <= 1'b0;
            length_err_sticky  <= 1'b0;
            in_count           <= 32'd0;
            out_count          <= 32'd0;
            no_progress_cycles <= 32'd0;
        end else begin
            if (clear_status_pulse) begin
                done_sticky        <= 1'b0;
                timeout_err_sticky <= 1'b0;
                length_err_sticky  <= 1'b0;
            end

            if (start_pulse && !run_active && frame_words_nonzero) begin
                run_active         <= 1'b1;
                done_sticky        <= 1'b0;
                timeout_err_sticky <= 1'b0;
                length_err_sticky  <= 1'b0;
                in_count           <= 32'd0;
                out_count          <= 32'd0;
                no_progress_cycles <= 32'd0;
            end

            if (run_active) begin
                if (in_hs) begin
                    if (in_last_expected) begin
                        // On expected last beat, TLAST should be asserted.
                        if (!s_axis_echo_tlast) begin
                            length_err_sticky <= 1'b1;
                            err_count <= err_count + 1'b1;
                        end
                    end else begin
                        in_count <= in_count + 1'b1;
                        // Early TLAST indicates input length mismatch.
                        if (s_axis_echo_tlast) begin
                            length_err_sticky <= 1'b1;
                            err_count <= err_count + 1'b1;
                        end
                    end
                end

                if (out_hs) begin
                    if (out_last_expected) begin
                        done_sticky <= 1'b1;
                        run_active  <= 1'b0;
                    end else begin
                        out_count <= out_count + 1'b1;
                    end
                end

                if (progress_hs) begin
                    no_progress_cycles <= 32'd0;
                end else if (timeout_cycles_reg != 32'd0) begin
                    if (no_progress_cycles >= (timeout_cycles_reg - 1'b1)) begin
                        timeout_err_sticky <= 1'b1;
                        err_count <= err_count + 1'b1;
                        run_active <= 1'b0;
                    end else begin
                        no_progress_cycles <= no_progress_cycles + 1'b1;
                    end
                end
            end
        end
    end
end

//-----------------------------------------------------------------------------
// 2D FFT core
//-----------------------------------------------------------------------------
fft_2D #(
    .DATA_WIDTH         (DATA_WIDTH),
    .NR                 (NR),
    .NA                 (NA),
    .AXI_ADDR_WIDTH     (AXI_ADDR_WIDTH),
    .AXI_DATA_WIDTH     (AXI_DATA_WIDTH),
    .TRANSPOSE_BASE_ADDR(TRANSPOSE_DDR_BASE_ADDR)
) u_fft_2d (
    .clk                (clk),
    .sram_clk           (clk),
    .sram_clk_locked    (1'b1),
    .rst_n              (rst_n),

    .i_echo_valid       (fft_i_valid),
    .o_echo_ready       (fft_i_ready),
    .i_echo_real        (s_axis_echo_tdata[DATA_WIDTH*2-1:DATA_WIDTH]),
    .i_echo_imag        (s_axis_echo_tdata[DATA_WIDTH-1:0]),

    .o_result_real      (fft_o_real),
    .o_result_imag      (fft_o_imag),
    .o_result_valid     (fft_o_valid),
    .i_downstream_ready (fft_o_ready),

    .cfg_transpose_store(cfg_transpose_store_reg),

    .m_axi_trans_awaddr (m_axi_trans_awaddr),
    .m_axi_trans_awlen  (m_axi_trans_awlen),
    .m_axi_trans_awsize (m_axi_trans_awsize),
    .m_axi_trans_awburst(m_axi_trans_awburst),
    .m_axi_trans_awvalid(m_axi_trans_awvalid),
    .m_axi_trans_awready(m_axi_trans_awready),
    .m_axi_trans_wdata  (m_axi_trans_wdata),
    .m_axi_trans_wstrb  (m_axi_trans_wstrb),
    .m_axi_trans_wlast  (m_axi_trans_wlast),
    .m_axi_trans_wvalid (m_axi_trans_wvalid),
    .m_axi_trans_wready (m_axi_trans_wready),
    .m_axi_trans_bresp  (m_axi_trans_bresp),
    .m_axi_trans_bvalid (m_axi_trans_bvalid),
    .m_axi_trans_bready (m_axi_trans_bready),
    .m_axi_trans_araddr (m_axi_trans_araddr),
    .m_axi_trans_arlen  (m_axi_trans_arlen),
    .m_axi_trans_arsize (m_axi_trans_arsize),
    .m_axi_trans_arburst(m_axi_trans_arburst),
    .m_axi_trans_arvalid(m_axi_trans_arvalid),
    .m_axi_trans_arready(m_axi_trans_arready),
    .m_axi_trans_rdata  (m_axi_trans_rdata),
    .m_axi_trans_rresp  (m_axi_trans_rresp),
    .m_axi_trans_rlast  (m_axi_trans_rlast),
    .m_axi_trans_rvalid (m_axi_trans_rvalid),
    .m_axi_trans_rready (m_axi_trans_rready),
    .sram_WE_n          (sram_WE_n),
    .sram_CE_n          (sram_CE_n),
    .sram_CE_2          (sram_CE_2),
    .sram_OE_n          (sram_OE_n),
    .sram_addr          (sram_addr),
    .sram_data          (sram_data)
);

wire unused_axil = |s_axi_awprot | |s_axi_arprot | |s_axis_echo_tkeep;

endmodule
